import{_ as n,a0 as a,w as p,s as u,ao as l,I as o,a1 as s,A as i,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"在 Firefox 和 Chrome 中轻松截取完整网页截图 | LCTT x X-CMD","titleTemplate":false,"description":"在 Firefox 和 Chrome 中轻松截取完整网页截图 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Firefox 和 Chrome 中轻松截取完整网页截图 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Firefox 和 Chrome 中轻松截取完整网页截图 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230808 Easily Take Full Webpage Screenshots in Firefox and Chrome","title":"在 Firefox 和 Chrome 中轻松截取完整网页截图","tag":"202308","desc":""},"relativePath":"202308/20230808 Easily Take Full Webpage Screenshots in Firefox and Chrome.md","filePath":"[post].md"}'),f={name:"202308/20230808 Easily Take Full Webpage Screenshots in Firefox and Chrome.md"};function m(d,e,h,b,x,g){const r=a("Link");return p(),u("div",null,[e[21]||(e[21]=l('<h1 id="在-firefox-和-chrome-中轻松截取完整网页截图" tabindex="-1">在 Firefox 和 Chrome 中轻松截取完整网页截图 <a class="header-anchor" href="#在-firefox-和-chrome-中轻松截取完整网页截图" aria-label="Permalink to “在 Firefox 和 Chrome 中轻松截取完整网页截图”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202308/30/132752rfrq7af9sqraz76r.jpg" alt=""></p><blockquote><p>Firefox 浏览器内置了截屏工具，你可以用它对整个网页进行截屏。Chrome 浏览器也有同样的功能。</p></blockquote><p>截屏来捕获信息是很常见的。</p><p>但你知道你可以在 Firefox 中截取整个网页的截图吗？Firefox 附带一个内置的截图工具，允许你截取选定区域、可见屏幕区域甚至整个网页的截图。</p><p>这意味着如果你想保存网页供以后参考，你可以快速捕获整个网页。</p><p>Chrome 也有截图功能，但稍微复杂一些。</p><p>在本教程中，我将引导你完成以下内容：</p><ul><li>如何在 Firefox 中截图</li><li>如何在 Chrome 中截图</li><li>使用 Nimbus 扩展获得比内置的截屏更多的功能</li></ul><p>那么让我们从第一个开始。</p><h3 id="在-firefox-中截取网页截图" tabindex="-1">在 Firefox 中截取网页截图 <a class="header-anchor" href="#在-firefox-中截取网页截图" aria-label="Permalink to “在 Firefox 中截取网页截图”">​</a></h3><p>Firefox 的内置工具可让你通过单击选择整个屏幕、整个页面，甚至特定段落。</p><h4 id="步骤-1-访问截图工具" tabindex="-1">步骤 1：访问截图工具 <a class="header-anchor" href="#步骤-1-访问截图工具" aria-label="Permalink to “步骤 1：访问截图工具”">​</a></h4><p>要启动截图程序，请在使用 Firefox 时按 <code>Ctrl + Shift + s</code>。</p><p>如果你不总是能记住快捷方式，也可以从右键单击菜单访问该工具。</p><p><img src="https://itsfoss.com/content/images/2023/08/take-screenshot-firefox.png" alt="Screenshot tool can also be accessed from right-click context menu"></p><p>如果你经常截图，那么将该程序添加到工具栏将是一个好主意。为此，你只需执行三个简单步骤：</p><ol><li>首先，右键单击工具栏并选择 “<ruby>自定义工具栏<rt>Customize Toolbar</rt></ruby>” 选项</li><li>找到 “<ruby>截图<rt>Screenshot</rt></ruby>” 程序并将其拖至工具栏</li><li>点击 “<ruby>完成<rt>Done</rt></ruby>” 按钮即可</li></ol><p>还困惑吗？ 操作方法如下：</p><p><img src="https://itsfoss.com/content/images/2023/08/Add-screenshot-feature-to-Firefox-browser-1.gif" alt=""></p><p>启用后，你可以单击刚刚拖动到工具栏的截图图标。</p><h4 id="步骤-2-在-firefox-中截图" tabindex="-1">步骤 2：在 Firefox 中截图 <a class="header-anchor" href="#步骤-2-在-firefox-中截图" aria-label="Permalink to “步骤 2：在 Firefox 中截图”">​</a></h4><p>当你启动截图工具时，它会提示两个选项：“<ruby>保存整页<rt>Save full page</rt></ruby>” 和 “<ruby>保存可见<rt>Save visible</rt></ruby>”。这里：</p><ul><li>保存整页将捕获整个网页</li><li>保存可见只会捕获当前帧中可见的内容</li></ul><p>但如果你想捕获特定部分，你可以使用鼠标光标选择该部分并保存：</p><p><img src="https://itsfoss.com/content/images/2023/08/Capture-specific-part-of-webpage-to-screenshot-in-Firefox.gif" alt=""></p><p>如你所见，有两个选项：<ruby>下载<rt>Download</rt></ruby> 或 <ruby>复制<rt>Copy</rt></ruby>（到剪贴板，以便你可以将其粘贴到文档或编辑工具中）。你可以根据你的场景使用其中之一。</p><h3 id="在-chrome-中截取网页截图" tabindex="-1">在 Chrome 中截取网页截图 <a class="header-anchor" href="#在-chrome-中截取网页截图" aria-label="Permalink to “在 Chrome 中截取网页截图”">​</a></h3><p>在 Chrome 中截取全部网页截图比在 Firefox 中要复杂一些，因为它隐藏在开发人员选项下。</p><p>不用担心！你将通过以下步骤做到：</p><ul><li>打开菜单，进入 “<ruby>更多工具<rt>More Tools</rt></ruby>-&gt;<ruby>开发者工具<rt>Developer tools</rt></ruby>”。或者，你可以按 <code>Ctrl + Shift + l</code> 进入开发者工具目录。</li><li>按 <code>Ctrl + Shift + p</code> 并输入 <code>screenshot</code>（LCTT 译注：在中文环境中请输入 “屏幕截图”）</li><li>选择区域或整个页面，然后回下载截图。</li></ul><p>让我向你展示如何做到这一点：</p><p><img src="https://itsfoss.com/content/images/2023/08/Take-screenshots-in-Google-chrome-without-any-extension-2-.gif" alt=""></p><p>这几乎就是 Chrome 所能提供的一切。</p><h3 id="如何使用扩展程序截图" tabindex="-1">如何使用扩展程序截图 <a class="header-anchor" href="#如何使用扩展程序截图" aria-label="Permalink to “如何使用扩展程序截图”">​</a></h3><blockquote><p>✋ 非自由和开源软件警告！这里讨论的 Nimbus 扩展不是开源的。</p></blockquote><p>如果你想要更多功能，例如添加延迟、水印或符号，那么你必须使用扩展程序。</p><p>为此，我建议使用 Nimbus，它几乎可以让你执行任何本地安装的截图工具可以执行的所有操作。</p><p>下载 Firefox 版 Nimbus：</p>',39)),o("blockquote",null,[o("p",null,[o("strong",null,[s(r,{href:"https://addons.mozilla.org/en-US/firefox/addon/nimbus-screenshot/?utm_source=addons.mozilla.org&utm_medium=referral&utm_content=search"},{default:i(()=>[...e[0]||(e[0]=[t("Firefox 版 Nimbus",-1)])]),_:1})])])]),e[22]||(e[22]=o("p",null,"下载 Chrome 版 Nimbus：",-1)),o("blockquote",null,[o("p",null,[o("strong",null,[s(r,{href:"https://chrome.google.com/webstore/detail/nimbus-screenshot-screen/bpconcjcammlapcogcnnelfmaeghhagj"},{default:i(()=>[...e[1]||(e[1]=[t("Chrome 版 Nimbus",-1)])]),_:1})])])]),e[23]||(e[23]=l('<blockquote><p>📋 只有 Nimbus 的 Chrome 扩展具有视频录制功能。</p></blockquote><p>完成安装后，<strong>请务必注册 Nimbus 以启用所有功能。</strong></p><p>单击 Nimbus 扩展图标，你会看到多个选项：</p><p><img src="https://itsfoss.com/content/images/2023/08/Use-nimbus-extension-to-take-full-screen-screenshots-in-chrome-and-firefox.png" alt=""></p><p>你可以选择任何显示的功能，完成后，根据捕获后进行的操作（我选择编辑），它将直接下载截图，打开编辑器或将其发送到任何选定的云提供商。</p><p>如果你也将 “<ruby>编辑<rt>Edit</rt></ruby>” 作为捕获后的操作，那么它将打开一个编辑器，你可以在其中对捕获的截图进行编辑：</p><p><img src="https://itsfoss.com/content/images/2023/08/Edit-screenshots-captured-in-Firefox-and-Chrome.png" alt=""></p><p>如果你想添加水印、了解/更改快捷方式、更改截图的格式等，请打开 Nimbus 并点击小齿轮按钮：</p><p><img src="https://itsfoss.com/content/images/2023/08/Additional-settings-of-Nimbus.png" alt=""></p><p>只是一个扩展却有非常酷的功能。不是吗？</p><blockquote><p>💡 如果你经常截屏，你可能需要将 Nimbus 扩展固定到任务栏。</p></blockquote><h3 id="想要更多功能吗-使用截图工具" tabindex="-1">想要更多功能吗？使用截图工具 <a class="header-anchor" href="#想要更多功能吗-使用截图工具" aria-label="Permalink to “想要更多功能吗？使用截图工具”">​</a></h3><p>如果你不想受到扩展功能的束缚，那么需要尝试具有更多功能的截图工具，这些工具可以在整个系统的任何地方使用。</p>',13)),o("p",null,[e[3]||(e[3]=t("如果你是 Linux 用户，那么我们有一份关于 ",-1)),s(r,{href:"https://itsfoss.com/take-screenshot-linux/"},{default:i(()=>[...e[2]||(e[2]=[t("Linux 中截取和编辑截图的最佳工具",-1)])]),_:1}),e[4]||(e[4]=t(" 的专门指南：",-1))]),o("blockquote",null,[o("p",null,[o("strong",null,[s(r,{href:"https://itsfoss.com/take-screenshot-linux/"},{default:i(()=>[...e[5]||(e[5]=[t("Linux 中截取和编辑截图的最佳工具",-1)])]),_:1})])])]),e[24]||(e[24]=o("p",null,"我希望你喜欢这个快速技巧。",-1)),e[25]||(e[25]=o("p",null,"（题图：MJ/76cc0d02-fb37-4bd0-94ec-fc249c1f537e）",-1)),e[26]||(e[26]=o("hr",null,null,-1)),o("p",null,[e[7]||(e[7]=t("via: ",-1)),s(r,{href:"https://itsfoss.com/firefox-screenshot/"},{default:i(()=>[...e[6]||(e[6]=[t("https://itsfoss.com/firefox-screenshot/",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("作者：",-1)),s(r,{href:"https://itsfoss.com/author/sagar/"},{default:i(()=>[...e[8]||(e[8]=[t("Sagar Sharma",-1)])]),_:1}),e[13]||(e[13]=t(" 选题：",-1)),s(r,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[9]||(e[9]=[t("lujun9972",-1)])]),_:1}),e[14]||(e[14]=t(" 译者：",-1)),s(r,{href:"https://github.com/geekpi"},{default:i(()=>[...e[10]||(e[10]=[t("geekpi",-1)])]),_:1}),e[15]||(e[15]=t(" 校对：",-1)),s(r,{href:"https://github.com/wxy"},{default:i(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[18]||(e[18]=t("本文由 ",-1)),s(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原创编译，",-1)),s(r,{href:"https://linux.cn/"},{default:i(()=>[...e[17]||(e[17]=[t("Linux中国",-1)])]),_:1}),e[20]||(e[20]=t(" 荣誉推出",-1))])])}const k=n(f,[["render",m]]);export{c as __pageData,k as default};
